/* ==========================================================================
   4. ANIMATIONS
   ========================================================================== */

/* Heading Text Animation */
[data-anim="heading"] .char {
  will-change: transform;
}
[data-anim="heading"] .word {
  will-change: transform;
  perspective: 1000px;
  transform-style: preserve-3d;
}
[data-anim="heading"] .line {
  will-change: transform;
  overflow: hidden;
  perspective: 1000px;
  transform-style: preserve-3d;
}

/* Appear on Scroll */
[data-appear]{
    opacity: 0;
    transform: translateY(1.5rem) scale(0.94);
    filter: blur(0.25rem);
    will-change: opacity, transform, filter;
    animation: appear 400ms ease forwards;
    animation-delay: calc(var(--index) * 0.1s);
}
@keyframes appear {
    to {
      opacity: 1;
      transform: translateY(0) scale(1);
      filter: blur(0);
    }
}

/* Hero Section Animations */
.hero_bg {
  opacity: 0;
  transform: scale(1.2);
  animation: fadeInHero 0.75s ease forwards;
}
[hero-anim="screen"] {
  transform: translateY(20%);
  opacity: 0; 
  animation: heroScreenIn 0.3s ease-out 1s forwards;
}
@keyframes heroScreenIn {
  from {
    transform: translateY(20%);
    opacity: 0;
  }
  to {
    transform: translateY(0%);
    opacity: 1;
  }
}
@keyframes fadeInHero {
  from {
    opacity: 0;
    transform: scale(4.2);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Button & Interactive Effects */
.play-button {
