/* ==========================================================================
   5. DATA TABLES
   ========================================================================== */

/* HTML TABLE Container */
div:has(> table) {
    width: 100%;
    overflow-x: auto;
    overflow-y: visible;
    -webkit-overflow-scrolling: touch;
    margin: 2rem 0;
    border-radius: 0.5rem;
    border: 0.125rem solid var(--alpha--white-10);
}

div:has(> table)::-webkit-scrollbar {
    height: 0.5rem;
}

div:has(> table)::-webkit-scrollbar-track {
    background: var(--alpha--white-10);
    border-radius: 0.25rem;
}

div:has(> table)::-webkit-scrollbar-thumb {
    background: var(--alpha--white-20);
    border-radius: 0.25rem;
}

div:has(> table)::-webkit-scrollbar-thumb:hover {
    background: var(--alpha--white-30);
}

/* Table Styles */
table {
    width: 100%;
    min-width: 37.5rem;
    border-collapse: separate;
    border-spacing: 0;
    font-size: 0.95rem;
    border-radius: 0.5rem;
    overflow: hidden;
}

thead {
    background-color: var(--alpha--white-4);
    position: sticky;
    top: 0;
    z-index: 10;
}

thead tr:first-child th:first-child {
    border-top-left-radius: 0.5rem;
}

thead tr:first-child th:last-child {
    border-top-right-radius: 0.5rem;
}

th {
    padding: 1rem;
    text-align: left;
    font-weight: 600;
    color: var(--alpha--white-70);
    border-bottom: 0.125rem solid var(--alpha--white-4);
    white-space: nowrap;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.03125rem;
}

td {
    padding: 1rem;
    border-bottom: 0.0625rem solid var(--alpha--white-4);
    vertical-align: middle;
    color: var(--alpha--white-60);
}

tbody tr {
    transition: background-color 0.2s ease;
}

tbody tr:hover {
    background-color: var(--alpha--white-10);
}

tbody tr:last-child td {
    border-bottom: none;
}

tbody tr:last-child td:first-child {
    border-bottom-left-radius: 0.5rem;
}

tbody tr:last-child td:last-child {
    border-bottom-right-radius: 0.5rem;
}

tbody tr:nth-child(even) {
    background-color: var(--alpha--white-4);
}

/* Responsive Table Breakpoints */
@media (max-width: 48rem) {
    div:has(> table) {
        margin: 1.5rem 0;
        border-radius: 0.375rem;
    }

    div:has(> table)::-webkit-scrollbar-thumb:hover {
        background: var(--alpha--white-30);
    }

    table {
        font-size: 0.85rem;
        border-radius: 0.375rem;
    }

    thead tr:first-child th:first-child {
        border-top-left-radius: 0.375rem;
    }

    thead tr:first-child th:last-child {
        border-top-right-radius: 0.375rem;
    }

    tbody tr {
        transition: none;
    }

    tbody tr:hover {
        background-color: transparent;
    }

    tbody tr:nth-child(even) {
        background-color: var(--alpha--white-4);
    }

    tbody tr:nth-child(even):hover {
        background-color: var(--alpha--white-4);
    }

    tbody tr:last-child td:first-child {
        border-bottom-left-radius: 0.375rem;
    }

    tbody tr:last-child td:last-child {
        border-bottom-right-radius: 0.375rem;
    }

    th,
    td {
        padding: 0.75rem 0.5rem;
    }
}

@media (max-width: 30rem) {
    div:has(> table)::-webkit-scrollbar-thumb:hover {
        background: var(--alpha--white-30);
    }

    table {
        font-size: 0.8rem;
        min-width: 31.25rem;
        border-radius: 0.375rem;
    }

    thead tr:first-child th:first-child {
        border-top-left-radius: 0.375rem;
    }

    thead tr:first-child th:last-child {
