    }

    tbody tr:nth-child(even):hover {
        background-color: var(--alpha--white-4);
    }

    tbody tr:last-child td:first-child {
        border-bottom-left-radius: 0.375rem;
    }

    tbody tr:last-child td:last-child {
        border-bottom-right-radius: 0.375rem;
    }

    th,
    td {
        padding: 0.5rem;
    }
}

